using HakutaiKagami.Core.Messaging;
namespace HakutaiKagami.Core.Contracts;
public sealed record NewMilitaryCaseView(EntityId Id,int Number,long At,long Revision);
public static partial class NewGameMilitary
{
    public const string RenewalContract="same-principal-garrison-lifetime-ledger-distinct-case-no-reset-v1";
    static NewMilitaryRequest? CaseStart(ContractWorld w,long? at=null,long? rev=null)=>w.NewMilitary?.Requests.LastOrDefault(q=>q.Input.Action==NewMilitaryAction.Request&&Before(q.At,q.Revision,at??w.ElapsedSeconds,rev??w.CommitSequence));
    static NewMilitaryRequest[] CaseRequests(ContractWorld w,long? at=null,long? rev=null){var root=CaseStart(w,at,rev);return root==null?[]:w.NewMilitary!.Requests.Where(q=>q.Revision>=root.Revision&&Before(q.At,q.Revision,at??w.ElapsedSeconds,rev??w.CommitSequence)).ToArray();}
    static MilitaryEvent[] CaseEvents(ContractWorld w,long? at=null,long? rev=null){var root=CaseStart(w,at,rev);return root==null?[]:w.NewMilitary!.Events.Where(e=>EventCase(w,e)==root.Input.Id&&Before(e.At,e.Revision,at??w.ElapsedSeconds,rev??w.CommitSequence)).ToArray();}
    static bool SameMilitaryCase(ContractWorld w,TroopDispatch original)=>CaseStart(w,original.At,original.Revision)?.Input.Id==CaseStart(w)?.Input.Id;
    public static NewMilitaryCaseView[] Cases(ContractWorld w)=>(w.NewMilitary?.Requests??[]).Where(q=>q.Input.Action==NewMilitaryAction.Request).Select((q,n)=>new NewMilitaryCaseView(q.Input.Id,n+1,q.At,q.Revision)).ToArray();
    static bool CanRenewKnown(ContractWorld w,long at,long rev){var s=w.NewMilitary;if(s==null)return false;var service=NewGameService.View(w,at,rev);bool closed=CaseEvents(w,at,rev).Where(e=>Known(w,e,at,rev)).Select(e=>Read(w,e)).Any(n=>n.Effect is MilitaryEffect.Returned or MilitaryEffect.Refused or MilitaryEffect.Expired);return closed&&((service.Principal==s.Terms.Principal&&service.House==s.Terms.Owner)||OwnAuthorityCase(w,at,rev))&&Local(w);}
    static bool CanRenew(ContractWorld w)=>CanRenewKnown(w,w.ElapsedSeconds,w.CommitSequence)&&!Deployed(w)&&!Outstanding(w,w.ElapsedSeconds,w.CommitSequence)&&!CustodyAt(w,w.ElapsedSeconds,w.CommitSequence)&&CarryAt(w,w.ElapsedSeconds,w.CommitSequence)==0;
    static EntityId EventCase(ContractWorld w,MilitaryEvent e){Need(e.Source!=null,"軍務効果の出典がありません");var q=w.NewMilitary!.Requests.SingleOrDefault(q=>e.Effect==MilitaryEffect.PickedUp?q.Input.Id.Value==e.Source:q.Message==e.Source);if(q!=null)return CaseStart(w,q.At,q.Revision)!.Input.Id;var m=w.Messaging.Messages.SingleOrDefault(m=>m.Id==e.Source);var root=Cases(w).SingleOrDefault(c=>c.Id.Value==m?.CorrelationId);if(root!=null)return root.Id;var historical=CaseStart(w,e.At,e.Revision);Need(historical!=null,"軍務効果の案件がありません");return historical.Input.Id;}
    static void UpdateHistoricalInquiries(ContractWorld w){var current=CaseStart(w)!.Input.Id;foreach(var q in w.NewMilitary!.Requests.Where(q=>q.Input.Action==NewMilitaryAction.Inquire&&q.Message!=null&&CaseStart(w,q.At,q.Revision)!.Input.Id!=current&&MessageFlow.Knows(w.Messaging,q.Message,w.NewMilitary.Terms.Principal.Value)&&!w.NewMilitary.Events.Any(e=>e.Effect==MilitaryEffect.StatusSent&&e.Source==q.Message)).ToArray()){var root=CaseStart(w,q.At,q.Revision)!.Input.Id;var e=w.NewMilitary.Events.LastOrDefault(e=>EventCase(w,e)==root&&(e.Effect is MilitaryEffect.Returned or MilitaryEffect.Permission or MilitaryEffect.Expired or MilitaryEffect.Refused or MilitaryEffect.CombatPermission or MilitaryEffect.EngagementPermission or MilitaryEffect.EngagementRejected or MilitaryEffect.EngagementCancelled));Announce(w,MilitaryEffect.StatusSent,q.Message!,e?.At??w.ElapsedSeconds,e?.Effect??MilitaryEffect.StatusSent,root);}}
}
